$((() => {
    "use strict";

    // ========================================================================
    // SAM Data Snapshot v0.1.0 —— 给 SAM 配一本「相册」
    // 每层一张快照，和楼层绑在一起；回退了就把那层的样子直接贴回去，不惊动 AI。
    // 设计稿见同目录 design.md
    // ========================================================================

    const INSTANCE_KEY = "__sam_data_snapshot_widget_v1__";
    const WIDGET_ID = "sam-data-snapshot-root";
    const STYLE_ID = "sam-data-snapshot-style";
    const APP_NAME = "SAM Data Snapshot";
    const VERSION = "0.1.0";

    const META_KEY = "sam-data-snapshot";              // 相册存在聊天元数据里的名字
    const SETTINGS_KEY = "sam-data-snapshot-settings"; // 设置存在脚本变量里的名字
    const SAM_DATA_KEY = "SAM_data";                   // SAM 自己的变量名

    const SAM_DONE_EVENT = "SAM_RESPONSE_PROCESSING_COMPLETED"; // SAM 算完一层会喊
    const SAM_REFRESH_EVENT = "REFRESH_SAM_VARIABLES";          // 让 SAM 重新同步

    // SAM 的底账块（写回正文用，格式与 SAM 完全一致）
    const LEDGER_START = "$$$$$$data_block$$$$$$";
    const LEDGER_END = "$$$$$$data_block_end$$$$$$";
    const LEDGER_RE = /\$\$\$\$\$\$data_block\$\$\$\$\$\$[\s\S]*?\$\$\$\$\$\$data_block_end\$\$\$\$\$\$/g;
    const CHECKPOINT_RE = /(?:<!-- SAM_CHECKPOINT -->\s*)?<SAMCheckpoint>[\s\S]*?<\/SAMCheckpoint>/g;

    const DEFAULT_SETTINGS = {
        enabled: true,            // 自动快照 SAM_data（总闸）
        autoRestore: true,        // 回退自动恢复变量
        writeLedgerBlock: true,   // 补写 data_block（纯文字，不连 AI）
        askSamRefresh: false,     // 恢复后同步 SAM（本地重拼，默认关）
        keepCount: 20,            // 快照上限 10-50
        watchMs: 3000,            // 巡检间隔（毫秒）
        maxSnapshotChars: 262144, // 单张快照上限（字符）
        quiet: false,             // 免打扰
        uiLeft: null,             // 书本按钮位置（拖动后记住）
        uiTop: null,
        edge: null,               // 贴在哪条边：left / right / top / bottom
        uiW: null,                // 面板宽度（拖动右下角后记住）
        uiH: null                 // 面板高度
    };

    // 纯逻辑核心（不碰 DOM / 不碰酒馆，方便单独测试）
    /* @CORE-START */
    const CORE = {
        /** 稳定序列化：键排序，保证同样的内容永远同样的字符串 */
        stableStringify(value) {
            const walk = (val) => {
                if (val === null || typeof val !== "object") {
                    if (typeof val === "number" && !Number.isFinite(val)) return "null";
                    if (typeof val === "undefined") return "null";
                    return JSON.stringify(val);
                }
                if (Array.isArray(val)) return "[" + val.map(walk).join(",") + "]";
                const keys = Object.keys(val).sort();
                return "{" + keys.map(k => JSON.stringify(k) + ":" + walk(val[k])).join(",") + "}";
            };
            try { return walk(value); } catch (e) { return "{}"; }
        },

        /** 短哈希（FNV-1a 32 位，base36） */
        hashString(text) {
            let h = 0x811c9dc5;
            const s = String(text || "");
            for (let i = 0; i < s.length; i++) {
                h ^= s.charCodeAt(i);
                h = Math.imul(h, 0x01000193);
            }
            return (h >>> 0).toString(36);
        },

        hashObject(value) { return this.hashString(this.stableStringify(value)); },

        clone(value) {
            try { return JSON.parse(JSON.stringify(value)); } catch (e) { return value; }
        },

        /** 去掉正文里的底账块与旧检查点块，只留叙事 */
        cleanMessageText(mes) {
            return String(mes || "").replace(LEDGER_RE, "").replace(CHECKPOINT_RE, "").replace(/\n{3,}/g, "\n\n").trim();
        },

        /** 楼层指纹：不靠裸楼层号，删楼后还能对上号 */
        fingerprint(message, swipeId) {
            if (!message) return "";
            return CORE.hashString([CORE.baseFingerprint(message), String(swipeId == null ? 0 : swipeId)].join("\u0001"));
        },

        /** 不分页的指纹：只认"哪条消息"，用来判断那一层还在不在 */
        baseFingerprint(message) {
            if (!message) return "";
            const body = CORE.cleanMessageText(message.mes).slice(0, 400);
            return CORE.hashString([
                String(message.name || ""),
                String(message.send_date || message.sendDate || ""),
                body
            ].join("\u0001"));
        },

        byteSize(value) {
            try { return JSON.stringify(value).length; } catch (e) { return 0; }
        },

        /** 一眼看懂的徽标数字 */
        digestOf(data) {
            const d = (data && typeof data === "object") ? data : {};
            const summary = d.responseSummary && typeof d.responseSummary === "object" ? d.responseSummary : {};
            return {
                staticKeys: Object.keys(d.static && typeof d.static === "object" ? d.static : {}).length,
                events: Array.isArray(d.events) ? d.events.length : 0,
                volatile: Array.isArray(d.volatile) ? d.volatile.length : 0,
                L2: Array.isArray(summary.L2) ? summary.L2.length : 0,
                L3: Array.isArray(summary.L3) ? summary.L3.length : 0,
                time: typeof d.time === "string" ? d.time : ""
            };
        },

        /** 太大就瘦身：丢掉最不重要的那部分，保证主设定与记忆还在 */
        trimPayload(data, maxChars) {
            const limit = Math.max(4096, Number(maxChars) || 262144);
            if (CORE.byteSize(data) <= limit) return { data: CORE.clone(data), trimmed: false };
            const slim = CORE.clone(data) || {};
            if (Array.isArray(slim.events) && slim.events.length > 40) slim.events = slim.events.slice(-40);
            delete slim.volatile;
            if (CORE.byteSize(slim) <= limit) return { data: slim, trimmed: true };
            return { data: slim, trimmed: true };
        },

        clampKeep(value) {
            const n = Math.round(Number(value));
            if (!Number.isFinite(n)) return 20;
            return Math.min(50, Math.max(10, n));
        },

        /** 超出张数就挤掉最旧的（用户定的规则） */
        trimSnapshots(list, keepCount) {
            const items = Array.isArray(list) ? list.slice() : [];
            const keep = CORE.clampKeep(keepCount);
            if (items.length <= keep) return items;
            items.sort((a, b) => (Number(b.at) || 0) - (Number(a.at) || 0));
            return items.slice(0, keep);
        },

        normalizeMeta(raw) {
            const base = { version: 1, rev: 0, currentId: null, snapshots: [], undo: null };
            if (!raw || typeof raw !== "object") return base;
            const list = Array.isArray(raw.snapshots) ? raw.snapshots : [];
            base.rev = Number(raw.rev) || 0;
            base.currentId = raw.currentId || null;
            base.snapshots = list.filter(s => s && s.id && Number.isFinite(Number(s.floor)));
            base.undo = (raw.undo && raw.undo.data) ? raw.undo : null;
            return base;
        },

        /** 一层一页只留一张：同层同页的旧记录合并成最新的那张 */
        collapseSnapshots(list) {
            const items = Array.isArray(list) ? list : [];
            const keep = new Map();
            for (const s of items) {
                const key = String(s.floor) + "|" + String(s.swipeId);
                const prev = keep.get(key);
                if (!prev || (Number(s.at) || 0) >= (Number(prev.at) || 0)) keep.set(key, s);
            }
            const kept = new Set(keep.values());
            return items.filter(s => kept.has(s));
        },

        nextId(meta) {
            const rev = (Number(meta && meta.rev) || 0) + 1;
            return "sm_" + rev.toString(36) + "_" + Date.now().toString(36);
        },

        /** 先按指纹精确找，再退回「同一层」，最后退回「这一层之前最近的一张」 */
        findForFloor(list, floor, fp) {
            const items = Array.isArray(list) ? list : [];
            if (fp) {
                const exact = items.filter(s => s.fp === fp);
                if (exact.length) return exact.sort((a, b) => (Number(b.at) || 0) - (Number(a.at) || 0))[0];
            }
            const same = items.filter(s => Number(s.floor) === Number(floor));
            if (same.length) return same.sort((a, b) => (Number(b.at) || 0) - (Number(a.at) || 0))[0];
            const earlier = items.filter(s => Number(s.floor) <= Number(floor));
            if (earlier.length) return earlier.sort((a, b) => Number(b.floor) - Number(a.floor) || (Number(b.at) || 0) - (Number(a.at) || 0))[0];
            return null;
        },

        /** 把正文里所有「整本账」的原文抠出来（新格式 + 老的检查点格式） */
        findFullBlockTexts(mes) {
            const text = String(mes || "");
            const out = [];
            let m;
            const ledger = /\$\$\$\$\$\$data_block\$\$\$\$\$\$([\s\S]*?)\$\$\$\$\$\$data_block_end\$\$\$\$\$\$/g;
            while ((m = ledger.exec(text)) !== null) out.push(m[1]);
            const checkpoint = /<SAMCheckpoint>([\s\S]*?)<\/SAMCheckpoint>/g;
            while ((m = checkpoint.exec(text)) !== null) out.push(m[1]);
            return out;
        },

        flatten(value, prefix, out, depth) {
            const level = depth || 0;
            if (level > 4 || out.length > 400) return out;
            if (value === null || typeof value !== "object") { out.push([prefix, value]); return out; }
            const keys = Object.keys(value);
            if (!keys.length) { out.push([prefix + "{}", value]); return out; }
            for (const k of keys) CORE.flatten(value[k], prefix ? prefix + "." + k : k, out, level + 1);
            return out;
        },

        /** 两张快照比一比：多了什么、少了什么、改了什么 */
        diff(left, right) {
            const mapA = new Map(CORE.flatten(left || {}, "", [], 0));
            const mapB = new Map(CORE.flatten(right || "", "", [], 0));
            const added = [];
            const removed = [];
            const changed = [];
            for (const [path, value] of mapB) {
                if (!mapA.has(path)) added.push(path);
                else if (CORE.stableStringify(mapA.get(path)) !== CORE.stableStringify(value)) changed.push(path);
            }
            for (const path of mapA.keys()) if (!mapB.has(path)) removed.push(path);
            return { added, removed, changed };
        },

        /** 只看最外层字段名：这一层比上一层动了哪几块 */
        changedKeyNames(left, right) {
            const d = CORE.diff(left, right);
            const keys = [];
            for (const path of [].concat(d.added, d.changed, d.removed)) {
                const name = String(path).split(".")[0] || String(path);
                if (name && keys.indexOf(name) === -1) keys.push(name);
                if (keys.length >= 6) break;
            }
            return keys;
        },

        /** 拼一段带底账块的正文 */
        buildLedgerMessage(mes, data) {
            const clean = CORE.cleanMessageText(mes);
            let json = "{}";
            try { json = JSON.stringify(data || {}); } catch (e) { json = "{}"; }
            return `${clean}\n\n${LEDGER_START}\n${json}\n${LEDGER_END}`;
        }
    };
    /* @CORE-END */

    // ========================================================================
    // 环境
    // ========================================================================
    const win = (() => { try { if (window.top && window.top.document) return window.top; } catch (e) {} return window; })();
    const doc = (() => { try { if (win && win.document) return win.document; } catch (e) {} return document; })();

    const logger = {
        info: (...a) => console.log(`[${APP_NAME}]`, ...a),
        warn: (...a) => console.warn(`[${APP_NAME}]`, ...a),
        error: (...a) => console.error(`[${APP_NAME}]`, ...a)
    };

    // ========================================================================
    // 状态
    // ========================================================================
    let settings = Object.assign({}, DEFAULT_SETTINGS);
    let meta = CORE.normalizeMeta(null);
    let chatRef = null;
    let isWriting = false;
    let isRestoring = false;
    let lastPollHash = "";
    let rollbackTimer = null;
    let pollTimer = null;
    let skipDemoteUntil = 0;   // 刚恢复完的那几秒，不再把旧记录塞进撤回槽
    let suppressWatchUntil = 0; // 回退处理期间，巡检先别急着拍，免得抢在比对之前把相册顶掉
    let selectedId = null;
    let showJson = false;
    let suppressClick = false;
    let cleanups = [];

    const ui = { widget: null, panel: null, status: null, list: null, detail: null, undoBtn: null, resize: null, fab: null };

    // ========================================================================
    // 小工具
    // ========================================================================
    function say(message, type) {
        if (settings.quiet) { logger.info(message); return; }
        const kind = type || "success";
        try {
            if (typeof toastr !== "undefined" && typeof toastr[kind] === "function") {
                toastr[kind](`[${APP_NAME}] ${message}`);
                return;
            }
        } catch (e) {}
        logger.info(message);
    }

    function getChat() {
        try { return SillyTavern.getContext().chat || []; } catch (e) { return []; }
    }

    function getContext() {
        try { return SillyTavern.getContext(); } catch (e) { return null; }
    }

    function findLastAiIndex(chat) {
        const list = chat || getChat();
        for (let i = list.length - 1; i >= 0; i--) if (list[i] && !list[i].is_user) return i;
        return -1;
    }

    function swipeOf(message) {
        const id = Number(message && message.swipe_id);
        return Number.isFinite(id) ? id : 0;
    }

    function clockText(ts) {
        try {
            const d = new Date(Number(ts) || Date.now());
            const p = n => String(n).padStart(2, "0");
            return `${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
        } catch (e) { return ""; }
    }

    function escapeHtml(value) {
        return String(value == null ? "" : value).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
    }

    function on(target, type, handler, options) {
        if (!target || typeof target.addEventListener !== "function") return;
        target.addEventListener(type, handler, options);
        cleanups.push(() => target.removeEventListener(type, handler, options));
    }

    function bindEvent(name, handler, first) {
        if (typeof eventOn !== "function") return;
        try {
            const ret = first && typeof eventMakeFirst === "function"
                ? eventMakeFirst(name, handler)
                : eventOn(name, handler);
            if (ret && typeof ret.stop === "function") cleanups.push(() => { try { ret.stop(); } catch (e) {} });
        } catch (e) { logger.warn("绑定事件失败：", name, e); }
    }

    // ========================================================================
    // 设置（脚本变量，换聊天也一致）
    // ========================================================================
    function loadSettings() {
        try {
            const bag = getVariables({ type: "script" }) || {};
            const stored = bag[SETTINGS_KEY];
            settings = Object.assign({}, DEFAULT_SETTINGS, stored && typeof stored === "object" ? stored : {});
            settings.keepCount = CORE.clampKeep(settings.keepCount);
        } catch (e) {
            logger.warn("读取设置失败，用默认值。", e);
            settings = Object.assign({}, DEFAULT_SETTINGS);
        }
    }

    function saveSettings() {
        try {
            insertOrAssignVariables({ [SETTINGS_KEY]: CORE.clone(settings) }, { type: "script" });
        } catch (e) { logger.warn("保存设置失败。", e); }
    }

    // ========================================================================
    // 相册（聊天元数据）
    // ========================================================================
    function loadMeta() {
        chatRef = getChat();
        let raw = null;
        try {
            const ctx = getContext();
            raw = ctx && ctx.chatMetadata ? ctx.chatMetadata[META_KEY] : null;
        } catch (e) { raw = null; }
        meta = CORE.normalizeMeta(raw);
        // 老记录里的旧来源名归并到现行几种
        meta.snapshots.forEach(s => {
            if (s.source === "manual") s.source = "sam";
            else if (s.source === "pre-restore" || s.source === "pre-change") s.source = "watch";
        });
        const before = meta.snapshots.length;
        meta.snapshots = CORE.collapseSnapshots(meta.snapshots);
        if (meta.snapshots.length !== before) saveMeta();
    }

    function saveMeta() {
        try {
            const ctx = getContext();
            if (!ctx) return;
            if (typeof ctx.updateChatMetadata === "function") ctx.updateChatMetadata({ [META_KEY]: meta }, false);
            else if (ctx.chatMetadata) ctx.chatMetadata[META_KEY] = meta;
            if (typeof ctx.saveMetadata === "function") {
                const p = ctx.saveMetadata();
                if (p && typeof p.catch === "function") p.catch(err => logger.warn("保存聊天元数据失败。", err));
            }
        } catch (e) { logger.warn("保存相册失败。", e); }
    }

    // ========================================================================
    // 读写 SAM 的变量
    // ========================================================================
    function readSamData() {
        try {
            const bag = getVariables({ type: "chat" }) || {};
            const data = bag[SAM_DATA_KEY];
            return data && typeof data === "object" ? data : null;
        } catch (e) { return null; }
    }

    async function writeSamData(data) {
        const copy = CORE.clone(data);
        await updateVariablesWith(vars => {
            vars[SAM_DATA_KEY] = copy;
            return vars;
        }, { type: "chat" });
    }

    // ========================================================================
    // 拍照
    // ========================================================================
    async function takeSnapshot(source, options) {
        if (!settings.enabled) return null;
        const chat = getChat();
        if (!chat || !chat.length) return null;
        const floor = Number.isFinite(options && options.floor) ? options.floor : findLastAiIndex(chat);
        if (floor < 0) return null;
        const message = chat[floor];
        if (!message || message.is_user) return null;

        const data = readSamData();
        if (!data) return null; // SAM 不在，不拍照

        const swipeId = swipeOf(message);
        const fp = CORE.fingerprint(message, swipeId);
        const bfp = CORE.baseFingerprint(message);
        const hash = CORE.hashObject(data);
        const now = Date.now();

        const same = meta.snapshots.find(s => Number(s.floor) === floor && Number(s.swipeId) === swipeId && s.hash === hash);
        if (same) {
            same.at = now;
            same.fp = fp;
            saveMeta();
            return same;
        }

        // 一层一页只留一张：新的顶掉旧的，被顶掉的那张先放进「撤回槽」保住
        const prev = meta.snapshots
            .filter(s => Number(s.floor) === floor && Number(s.swipeId) === swipeId)
            .sort((a, b) => (Number(b.at) || 0) - (Number(a.at) || 0))[0] || null;
        const changedKeys = prev ? CORE.changedKeyNames(prev.data, data) : [];
        if (prev) {
            meta.snapshots = meta.snapshots.filter(s => s.id !== prev.id);
            if (Date.now() >= skipDemoteUntil) {
                meta.undo = {
                    id: "undo_" + Date.now().toString(36),
                    at: Date.now(),
                    floor: prev.floor,
                    swipeId: prev.swipeId,
                    hash: prev.hash,
                    data: CORE.clone(prev.data)
                };
            }
        }

        meta.rev = (Number(meta.rev) || 0) + 1;
        const payload = CORE.trimPayload(data, settings.maxSnapshotChars);
        const record = {
            id: CORE.nextId(meta),
            rev: meta.rev,
            at: now,
            floor,
            swipeId,
            fp,
            bfp,
            source: source || "auto",
            hash,
            size: CORE.byteSize(payload.data),
            trimmed: payload.trimmed,
            changedKeys,
            digest: CORE.digestOf(data),
            data: payload.data
        };
        meta.snapshots.push(record);
        meta.snapshots = CORE.trimSnapshots(meta.snapshots, settings.keepCount);
        meta.currentId = record.id;
        saveMeta();

        renderList();
        renderStatus();
        return record;
    }

    /** 回填：把过往楼层里已有的「整本账」抄成快照（精确，不推算） */
    async function backfillHistory(options) {
        const silent = !!(options && options.silent);
        const chat = getChat();
        if (!chat || !chat.length) return { found: 0, added: 0, broken: 0 };
        const limit = CORE.clampKeep(settings.keepCount);

        const candidates = [];
        let found = 0;
        let broken = 0;

        for (let i = 0; i < chat.length; i++) {
            const message = chat[i];
            if (!message || message.is_user) continue;
            const texts = CORE.findFullBlockTexts(message.mes);
            if (!texts.length) continue;
            let data = null;
            for (const text of texts) {
                found += 1;
                try {
                    const parsed = JSON.parse(text);
                    if (parsed && typeof parsed === "object") data = parsed;
                } catch (e) { broken += 1; }
            }
            if (data) candidates.push({ floor: i, message, data });
        }

        candidates.sort((a, b) => b.floor - a.floor); // 从最新的往回抄
        let added = 0;
        for (const item of candidates) {
            if (added >= limit) break;
            const swipeId = swipeOf(item.message);
            const fp = CORE.fingerprint(item.message, swipeId);
            const hash = CORE.hashObject(item.data);
            // 这一层已经有实时快照了就不动它，实时的那张更新
            const occupied = meta.snapshots.find(s => Number(s.floor) === item.floor && Number(s.swipeId) === swipeId);
            if (occupied) continue;
            const dup = meta.snapshots.find(s => s.fp === fp && s.hash === hash);
            if (dup) continue;

            meta.rev = (Number(meta.rev) || 0) + 1;
            const payload = CORE.trimPayload(item.data, settings.maxSnapshotChars);
            meta.snapshots.push({
                id: CORE.nextId(meta),
                rev: meta.rev,
                at: 1e12 + item.floor,   // 用楼层排序，永远排在实时快照之后
                floor: item.floor,
                swipeId,
                fp,
                bfp: CORE.baseFingerprint(item.message),
                source: "backfill",
                hash,
                size: CORE.byteSize(payload.data),
                trimmed: payload.trimmed,
                changedKeys: [],
                digest: CORE.digestOf(item.data),
                data: payload.data
            });
            added += 1;
        }

        if (added) {
            meta.snapshots = CORE.trimSnapshots(meta.snapshots, limit);
            saveMeta();
            renderList();
            renderStatus();
            renderDetail();
        }
        if (!silent) {
            if (found === 0) say("过往楼层里没有找到完整账本，没法回填", "info");
            else say(`过往找到 ${found} 处完整账本，补了 ${added} 张${broken ? `，另有 ${broken} 处坏了` : ""}`, added ? "success" : "info");
        }
        return { found, added, broken };
    }

    // ========================================================================
    // 贴回去
    // ========================================================================
    async function writeLedgerBlock(record, chat) {
        const floor = findLastAiIndex(chat);
        if (floor < 0) return false;
        const message = chat[floor];
        if (!message || message.is_user) return false;
        const next = CORE.buildLedgerMessage(message.mes, record.data);
        isWriting = true;
        try {
            message.mes = next;
            await setChatMessages([{ message_id: floor, message: next }]);
        } finally {
            setTimeout(() => { isWriting = false; }, 500);
        }
        return true;
    }

    async function restoreSnapshot(id, reason, attempt, opts) {
        if (isRestoring) return false;
        let record = meta.snapshots.find(s => s.id === id);
        const fromUndo = !record && meta.undo && meta.undo.data && (id === "__undo__" || meta.undo.id === id);
        if (fromUndo) record = Object.assign({}, meta.undo, { id: "__undo__", source: "undo" });
        if (!record) { say("找不到这张快照了", "warning"); return false; }

        isRestoring = true;
        try {
            const live = readSamData();
            const liveHash = live ? CORE.hashObject(live) : null;
            if (liveHash && liveHash === record.hash) {
                logger.info("已经是这一层的变量了，不用贴。");
                return true;
            }

            // 先记下「动之前」的样子进撤回槽（撤回自己不再记，避免来回打转）
            if (!(opts && opts.skipPre) && live) {
                meta.undo = {
                    id: "undo_" + Date.now().toString(36),
                    at: Date.now(),
                    floor: record.floor,
                    swipeId: record.swipeId,
                    hash: liveHash,
                    data: CORE.clone(live)
                };
            }

            // ① 补写 data_block：只是把快照写进正文末尾，纯文字操作，不连 AI、不花 token。
            //    没有这块，下次发消息时 SAM 会按历史重建，把我们刚贴的又拼回原样。
            if (settings.writeLedgerBlock) {
                try { await writeLedgerBlock(record, getChat()); }
                catch (e) { logger.warn("补写 data_block 失败，只写变量。", e); }
            }

            // ② 整份覆盖变量：这就是「把快照直接贴上去」
            await writeSamData(record.data);
            chatRef = getChat();
            skipDemoteUntil = Date.now() + 4000;      // 接下来这几秒，巡检别把旧记录塞进撤回槽
            suppressWatchUntil = Date.now() + 2500;   // 也别急着拍，先让复查跑完

            // ③ 默认不打扰 SAM（不喊它同步、不让它重算任何东西）。
            if (settings.askSamRefresh) {
                setTimeout(() => { try { eventEmit(SAM_REFRESH_EVENT); } catch (e) {} }, 260);
            }

            if (opts && opts.consume) {
                meta.undo = null;
            }
            saveMeta();

            say(reason === "undo"
                ? `已撤回，变量回到第 ${record.floor} 层改动之前的样子`
                : `第 ${record.floor} 层的变量已恢复${reason === "auto" ? "（自动）" : ""}，没让 AI 重算`, "success");
            renderStatus();
            renderList();
            renderDetail();
            if (!(opts && opts.consume)) scheduleVerify(record.id, Number(attempt) || 0);
            return true;
        } catch (e) {
            logger.error("恢复失败：", e);
            say("恢复的时候卡住了，原样保留着", "error");
            return false;
        } finally {
            isRestoring = false;
        }
    }

    /** 贴完回头再看两眼：被 SAM 又写回去就补一次，兜底的最后一环 */
    function scheduleVerify(id, attempt) {
        const origin = meta.snapshots.find(s => s.id === id);
        if (!origin) return;
        const target = {
            floor: origin.floor,
            swipeId: origin.swipeId,
            hash: origin.hash,
            data: CORE.clone(origin.data)
        };

        const check = async () => {
            if (isRestoring || isWriting) return;
            const live = readSamData();
            if (!live) return;
            if (CORE.hashObject(live) === target.hash) return; // 稳住了
            if (attempt >= 1) {
                say(`第 ${target.floor} 层又被 SAM 写回去了，相册里备份还在，可以再点一次恢复`, "warning");
                return;
            }
            attempt += 1;
            logger.warn("恢复后被 SAM 覆盖，自动再贴一次。", id);
            // 万一相册里那张已经被巡检顶掉，就用这份内存里的副本临时补一张去贴
            const exists = meta.snapshots.some(s => s.id === id);
            if (!exists) {
                meta.snapshots.push(Object.assign({ id: "__verify__", at: Date.now(), source: "watch", fp: "", bfp: "", size: 0, digest: {} }, target));
            }
            await restoreSnapshot(exists ? id : "__verify__", "auto", attempt, { skipPre: true });
            if (!exists) {
                meta.snapshots = meta.snapshots.filter(s => s.id !== "__verify__");
                saveMeta();
                renderList();
            }
        };

        // 看两次：刚贴完一次，隔几秒再看一次（SAM 重算慢的时候能兜住）
        setTimeout(() => { check().catch(e => logger.warn(e)); }, 1600);
        setTimeout(() => { check().catch(e => logger.warn(e)); }, 4400);
    }

    /** 打开聊天时看一眼：和相册不一样就直接恢复（只在自动恢复开着时） */
    async function nudgeOnLoad() {
        if (!settings.enabled || !settings.autoRestore) return;
        const chat = getChat();
        if (!chat || !chat.length) return;
        const floor = findLastAiIndex(chat);
        if (floor < 0) return;
        const message = chat[floor];
        const record = CORE.findForFloor(meta.snapshots, floor, CORE.fingerprint(message, swipeOf(message)));
        if (!record) return;
        const live = readSamData();
        if (!live) return;
        if (CORE.hashObject(live) === record.hash) return;
        await waitForSamIdle(4);
        await restoreSnapshot(record.id, "auto");
    }

    /** 楼层被删掉后，把那一层的快照一起清掉，并给剩下的快照重新对号 */
    function pruneDeletedFloors(deletedIndex) {
        const chat = getChat();
        if (!chat) return 0;
        const startAt = Number.isFinite(Number(deletedIndex)) ? Math.max(0, Number(deletedIndex)) : 0;
        const baseToFloor = new Map();
        for (let i = 0; i < chat.length; i++) {
            const message = chat[i];
            if (!message || message.is_user) continue;
            baseToFloor.set(CORE.baseFingerprint(message), i);
        }
        let removed = 0;
        const kept = [];
        for (const s of meta.snapshots) {
            // 尾巴被删：楼层已经超出聊天范围
            if (Number(s.floor) >= chat.length) { removed += 1; continue; }
            // 删的是后面的楼层，这条在它前面，没受影响，原样保留
            if (Number(s.floor) < startAt) { kept.push(s); continue; }
            if (!s.bfp) { kept.push(s); continue; } // 早期记录没有 bfp，保守留着
            const floor = baseToFloor.get(s.bfp);
            if (floor === undefined) { removed += 1; continue; } // 那一条消息已经不在了
            s.floor = floor; // 前面的楼层被删后整体前移，重新对号
            kept.push(s);
        }
        meta.snapshots = kept;
        if (removed) {
            if (meta.currentId && !meta.snapshots.some(s => s.id === meta.currentId)) meta.currentId = null;
            if (selectedId && !meta.snapshots.some(s => s.id === selectedId)) selectedId = null;
            saveMeta();
            renderStatus();
            renderList();
            renderDetail();
        }
        return removed;
    }

    /** 撤回槽：上一次改动之前的样子 */
    function findUndoRecord() {
        return (meta.undo && meta.undo.data) ? meta.undo : null;
    }

    /** 撤回一步：回到上一次改动之前的样子 */
    async function undoLastRestore() {
        if (isRestoring) return false;
        const undo = findUndoRecord();
        if (!undo) { say("现在没有可以撤回的操作", "info"); return false; }
        const ok = await restoreSnapshot("__undo__", "undo", 0, { skipPre: true, consume: true });
        if (ok) renderActions();
        return ok;
    }

    // ========================================================================
    // 回退检测
    // ========================================================================
    function samBusy() {
        try {
            const el = doc && doc.getElementById ? doc.getElementById("sam_status_display") : null;
            if (!el) return false;
            return /PROCESSING|SUMMARIZING|AWAIT_GENERATION/.test(el.textContent || "");
        } catch (e) { return false; }
    }

    async function waitForSamIdle(tries) {
        let left = Math.max(0, Number(tries) || 0);
        while (left > 0 && samBusy()) {
            await new Promise(r => setTimeout(r, 500));
            left -= 1;
        }
        return !samBusy();
    }

    async function checkRollback(reason) {
        if (!settings.enabled || isWriting || isRestoring) return;
        const chat = getChat();
        if (!chat || !chat.length) return;
        const floor = findLastAiIndex(chat);
        if (floor < 0) return;

        const message = chat[floor];
        const fp = CORE.fingerprint(message, swipeOf(message));
        const record = CORE.findForFloor(meta.snapshots, floor, fp);
        if (!record) return;

        const live = readSamData();
        const liveHash = live ? CORE.hashObject(live) : null;
        if (liveHash && liveHash === record.hash) return; // 已经对得上，安静

        // 自动恢复关着 = 完全不恢复，也不提醒（本版没有手动恢复）
        if (!settings.autoRestore) return;

        await waitForSamIdle(6);
        await restoreSnapshot(record.id, "auto");
    }

    function scheduleRollbackCheck(reason) {
        if (!settings.enabled) return;
        if (isWriting || isRestoring) return;
        // 从这一刻起，巡检先别拍：SAM 正在重算，别让它把相册里那张对的顶掉
        suppressWatchUntil = Date.now() + 5000;
        if (rollbackTimer) clearTimeout(rollbackTimer);
        rollbackTimer = setTimeout(() => { rollbackTimer = null; checkRollback(reason).catch(e => logger.warn(e)); }, 650);
    }

    function startWatcher() {
        if (pollTimer) clearInterval(pollTimer);
        pollTimer = setInterval(async () => {
            if (!settings.enabled || isWriting || isRestoring) return;
            if (Date.now() < suppressWatchUntil) return; // 回退处理中，先让比对跑完
            const data = readSamData();
            if (!data) return;
            const hash = CORE.hashObject(data);
            if (hash === lastPollHash) return;
            lastPollHash = hash;
            try { await takeSnapshot("watch"); } catch (e) { logger.warn(e); }
        }, Math.max(1000, Number(settings.watchMs) || 3000));
        cleanups.push(() => clearInterval(pollTimer));
    }

