            renderList(); renderDetail();
        });

        on(ui.detail, "click", async (e) => {
            if (!e.target || !e.target.classList || !e.target.classList.contains("sm-copy")) return;
            const record = meta.snapshots.find(s => s.id === selectedId);
            if (!record) return;
            try {
                await navigator.clipboard.writeText(JSON.stringify(record.data, null, 2));
                say("这一层的 JSON 复制好了", "success");
            } catch (err) {
                say("复制不了，手动选一下文本吧", "warning");
            }
        });

        root.querySelectorAll("[data-act]").forEach(btn => {
            on(btn, "click", async () => {
                const act = btn.dataset.act;
                if (act === "undo") {
                    btn.disabled = true;
                    try { await undoLastRestore(); } finally { btn.disabled = false; renderActions(); }
                } else if (act === "json") {
                    showJson = !showJson;
                    renderDetail();
                } else if (act === "backfill") {
                    btn.disabled = true;
                    try { await backfillHistory({ silent: false }); } finally { btn.disabled = false; }
                } else if (act === "export") {
                    exportAlbum();
                }
            });
        });

        bindDrag(fab);
        bindResize(ui.resize);
        restorePosition();
        on(win, "resize", () => { restorePosition(); });

        return true;
    }

    // ---- 书本按钮：可拖动，位置记在设置里 ----
    /** 设置里的数值可能是 null，别被 Number(null)=0 骗了 */
    function numOr(value, fallback) {
        const n = Number(value);
        return (value !== null && value !== undefined && Number.isFinite(n)) ? n : fallback;
    }

    function widgetBox() {
        const w = (ui.fab && ui.fab.offsetWidth) || (ui.widget && ui.widget.offsetWidth) || 46;
        const h = (ui.fab && ui.fab.offsetHeight) || (ui.widget && ui.widget.offsetHeight) || 46;
        return { w, h };
    }

    function applyWidgetPosition(left, top) {
        if (!ui.widget) return null;
        const { w, h } = widgetBox();
        const maxLeft = Math.max(0, (win.innerWidth || 1024) - w);
        const maxTop = Math.max(0, (win.innerHeight || 768) - h);
        const l = Math.min(maxLeft, Math.max(0, Math.round(Number(left) || 0)));
        const t = Math.min(maxTop, Math.max(0, Math.round(Number(top) || 0)));
        ui.widget.style.left = l + "px";
        ui.widget.style.top = t + "px";
        ui.widget.style.right = "auto";
        ui.widget.style.bottom = "auto";
        return { l, t };
    }

    function restorePosition() {
        if (!ui.widget) return;
        const { h } = widgetBox();
        const hasSaved = settings.uiLeft !== null && settings.uiLeft !== undefined
            && settings.uiTop !== null && settings.uiTop !== undefined
            && Number.isFinite(Number(settings.uiLeft)) && Number.isFinite(Number(settings.uiTop));
        if (hasSaved) applyWidgetPosition(settings.uiLeft, settings.uiTop);
        else applyWidgetPosition(16, (win.innerHeight || 768) - h - 96);
        applyEdgeClasses();
        placePanel();
    }

    /** 面板大小：用户拖过就按拖的来，没拖过就用默认 */
    function panelSize() {
        const w = Number(settings.uiW);
        const h = Number(settings.uiH);
        return {
            w: Number.isFinite(w) && w > 0 ? w : 432,
            h: Number.isFinite(h) && h > 0 ? h : 0
        };
    }

    function clampToViewport(panelW, panelH, left, top) {
        const vw = win.innerWidth || 1024;
        const vh = win.innerHeight || 768;
        const w = Math.min(Math.max(240, panelW), vw - 16);
        const h = Math.min(Math.max(220, panelH), vh - 16);
        const l = Math.min(Math.max(8, left), Math.max(8, vw - w - 8));
        const t = Math.min(Math.max(8, top), Math.max(8, vh - h - 8));
        return { w, h, l, t };
    }

    /** 面板跟着小钮走，同时永远留在屏幕里 */
    function placePanel() {
        if (!ui.panel || !ui.widget) return;
        const box = ui.widget.getBoundingClientRect();
        const vw = win.innerWidth || 1024;
        const vh = win.innerHeight || 768;
        const size = panelSize();

        // 先定宽（高度由内容撑或用户指定）
        const width = Math.min(size.w, vw - 16);
        ui.panel.style.width = Math.round(width) + "px";
        if (size.h) {
            ui.panel.style.height = Math.round(Math.min(size.h, vh - 16)) + "px";
            ui.panel.style.maxHeight = "none";
        } else {
            ui.panel.style.height = "";
            ui.panel.style.maxHeight = Math.round(vh - 16) + "px";
        }

        const panelW = ui.panel.offsetWidth || width;
        const panelH = ui.panel.offsetHeight || 420;
        const spaceBelow = vh - box.bottom;
        const spaceAbove = box.top;
        const openUp = spaceBelow < panelH + 16 && spaceAbove > spaceBelow;
        const top = openUp ? box.top - panelH - 10 : box.bottom + 10;
        const left = box.left + panelW > vw - 8 ? vw - panelW - 8 : box.left;

        const placed = clampToViewport(panelW, panelH, left, top);
        ui.panel.style.left = Math.round(placed.l) + "px";
        ui.panel.style.top = Math.round(placed.t) + "px";
        ui.panel.style.right = "auto";
        ui.panel.style.bottom = "auto";
    }

    /** 右下角的抓手：拖着改大小，松手记住 */
    function bindResize(grip) {
        if (!grip) return;
        const state = { active: false, id: null, sx: 0, sy: 0, sw: 0, sh: 0 };

        const down = (e) => {
            if (e.pointerType === "mouse" && e.button !== 0) return;
            state.active = true;
            state.id = e.pointerId;
            state.sx = e.clientX;
            state.sy = e.clientY;
            state.sw = ui.panel.offsetWidth;
            state.sh = ui.panel.offsetHeight;
            try { if (grip.setPointerCapture) grip.setPointerCapture(e.pointerId); } catch (err) {}
            e.preventDefault();
            e.stopPropagation();
        };

        const move = (e) => {
            if (!state.active || e.pointerId !== state.id) return;
            const vw = win.innerWidth || 1024;
            const vh = win.innerHeight || 768;
            const left = parseFloat(ui.panel.style.left) || 8;
            const top = parseFloat(ui.panel.style.top) || 8;
            const w = Math.max(240, Math.min(state.sw + (e.clientX - state.sx), vw - left - 8));
            const h = Math.max(220, Math.min(state.sh + (e.clientY - state.sy), vh - top - 8));
            ui.panel.style.width = Math.round(w) + "px";
            ui.panel.style.height = Math.round(h) + "px";
            ui.panel.style.maxHeight = "none";
            e.preventDefault();
        };

        const up = (e) => {
            if (!state.active) return;
            if (e && e.pointerId != null && e.pointerId !== state.id) return;
            state.active = false;
            settings.uiW = ui.panel.offsetWidth;
            settings.uiH = ui.panel.offsetHeight;
            saveSettings();
            placePanel();
        };

        on(grip, "pointerdown", down);
        on(win, "pointermove", move);
        on(win, "pointerup", up);
        on(win, "pointercancel", up);
    }

    /** 靠近屏幕边缘就吸附过去（左右上下一共四条边），贴边距离为 0，看着是"长"在边上 */
    function snapToEdge(pos) {
        const vw = win.innerWidth || 1024;
        const vh = win.innerHeight || 768;
        const { w, h } = widgetBox();
        const reach = 18; // 离边 18px 以内就吸过去
        let l = pos.l;
        let t = pos.t;
        const edges = [];

        if (l <= reach) { l = 0; edges.push("left"); }
        else if (l + w >= vw - reach) { l = vw - w; edges.push("right"); }

        if (t <= reach) { t = 0; edges.push("top"); }
        else if (t + h >= vh - reach) { t = vh - h; edges.push("bottom"); }

        return { l: Math.round(l), t: Math.round(t), snapped: edges.length > 0, edge: edges[0] || null };
    }

    /** 贴边后收成一条细条；面板开着或正在拖的时候恢复成圆钮 */
    function applyEdgeClasses() {
        if (!ui.widget) return;
        ["left", "right", "top", "bottom"].forEach(side => ui.widget.classList.remove("sm-peek-" + side));
        ui.widget.classList.remove("sm-peek");

        const edge = settings.edge;
        const peek = edge && ui.panel && ui.panel.hidden;
        if (!peek) {
            setPeekSize(0, 0);
            const vh = win.innerHeight || 768;
            applyWidgetPosition(numOr(settings.uiLeft, 16), numOr(settings.uiTop, vh - 46 - 96));
            return;
        }

        ui.widget.classList.add("sm-peek");
        ui.widget.classList.add("sm-peek-" + edge);

        // 收成细条：左右是竖条（宽 34 / 高 52），上下是横条（宽 52 / 高 34）
        const vw = win.innerWidth || 1024;
        const vh = win.innerHeight || 768;
        const vertical = (edge === "left" || edge === "right");
        const w = vertical ? 34 : 52;
        const h = vertical ? 52 : 34;
        setPeekSize(w, h);
        const l = edge === "left" ? 0
            : edge === "right" ? vw - w
            : Math.min(Math.max(0, Number(settings.uiLeft) || 0), Math.max(0, vw - w));
        const t = edge === "top" ? 0
            : edge === "bottom" ? vh - h
            : Math.min(Math.max(0, Number(settings.uiTop) || 0), Math.max(0, vh - h));
        ui.widget.style.left = Math.round(l) + "px";
        ui.widget.style.top = Math.round(t) + "px";
    }

    /** 真正改的是按钮本身的大小（外层容器跟着缩） */
    function setPeekSize(w, h) {
        if (ui.fab) {
            ui.fab.style.width = w ? w + "px" : "";
            ui.fab.style.height = h ? h + "px" : "";
        }
        if (!w) {
            ui.widget.style.width = "";
            ui.widget.style.height = "";
        }
    }

    /** 点一下按钮：抽屉式拉出 + 开关面板（自己处理，不等浏览器 click） */
    function handleFabTap() {
        suppressClick = true;
        setTimeout(() => { suppressClick = false; }, 120);
        const willOpen = !!(ui.panel && ui.panel.hidden);
        if (willOpen) pullOutFromEdge(); // 只有"要打开面板"时才脱离贴边
        togglePanel();
    }

    /** 点一下小灰条：像抽屉一样拉出来，脱离贴边，暂时不自动最小化 */
    function pullOutFromEdge() {
        if (!ui.widget || !settings.edge) return; // 没贴边就不用管
        const edge = settings.edge;
        settings.edge = null;
        ui.widget.classList.remove("sm-peek", "sm-peek-left", "sm-peek-right", "sm-peek-top", "sm-peek-bottom");
        setPeekSize(0, 0);

        const vw = win.innerWidth || 1024;
        const vh = win.innerHeight || 768;
        const inset = 16;
        let l = numOr(settings.uiLeft, inset);
        let t = numOr(settings.uiTop, vh - 46 - 96);
        if (edge === "left") l = inset;
        if (edge === "right") l = vw - 46 - inset;
        if (edge === "top") t = inset;
        if (edge === "bottom") t = vh - 46 - inset;
        const pos = applyWidgetPosition(l, t);
        if (pos) { settings.uiLeft = pos.l; settings.uiTop = pos.t; }
        saveSettings();
    }

    /** 从细条恢复成圆钮（拖动前先展开） */
    function expandFromPeek() {
        if (!ui.widget || !ui.widget.classList.contains("sm-peek")) return;
        ui.widget.classList.remove("sm-peek", "sm-peek-left", "sm-peek-right", "sm-peek-top", "sm-peek-bottom");
        setPeekSize(0, 0);
        const edge = settings.edge;
        const vw = win.innerWidth || 1024;
        const vh = win.innerHeight || 768;
        let l = numOr(settings.uiLeft, 16);
        let t = numOr(settings.uiTop, vh - 46 - 96);
        if (edge === "right") l = vw - 46;
        if (edge === "bottom") t = vh - 46;
        applyWidgetPosition(l, t);
    }

    /** 吸附时给一点小动画，不然会显得很突兀 */
    function animateWidgetTo(left, top) {
        if (!ui.widget) return;
        ui.widget.style.transition = "left .18s ease, top .18s ease";
        applyWidgetPosition(left, top);
        setTimeout(() => { if (ui.widget) ui.widget.style.transition = ""; }, 220);
    }

    function bindDrag(fab) {
        if (!fab) return;
        const state = { active: false, id: null, sx: 0, sy: 0, ox: 0, oy: 0, moved: false };

        const down = (e) => {
            if (e.pointerType === "mouse" && e.button !== 0) return;
            expandFromPeek(); // 先恢复成圆钮，不然抓手太小、拖不准
            const box = ui.widget.getBoundingClientRect();
            state.active = true;
            state.id = e.pointerId;
            state.sx = e.clientX;
            state.sy = e.clientY;
            state.ox = parseFloat(ui.widget.style.left);
            state.oy = parseFloat(ui.widget.style.top);
            if (!Number.isFinite(state.ox)) state.ox = box.left;
            if (!Number.isFinite(state.oy)) state.oy = box.top;
            state.moved = false;
            try { if (fab.setPointerCapture) fab.setPointerCapture(e.pointerId); } catch (err) {}
            e.preventDefault();
        };

        const move = (e) => {
            if (!state.active || e.pointerId !== state.id) return;
            const dx = e.clientX - state.sx;
            const dy = e.clientY - state.sy;
            if (!state.moved && Math.abs(dx) + Math.abs(dy) > 10) {
                state.moved = true;
                ui.widget.classList.add("sm-dragging"); // 真开始拖了才展开，避免点一下抽一下
            }
            if (state.moved) applyWidgetPosition(state.ox + dx, state.oy + dy);
        };

        const up = (e) => {
            if (!state.active) return;
            if (e && e.pointerId != null && e.pointerId !== state.id) return;
            state.active = false;
            ui.widget.classList.remove("sm-dragging");
            const dragged = state.moved;

            if (dragged) {
                const box = ui.widget.getBoundingClientRect();
                const raw = applyWidgetPosition(box.left, box.top) || { l: box.left, t: box.top };
                const snapped = snapToEdge(raw);
                if (snapped.snapped) animateWidgetTo(snapped.l, snapped.t);
                else applyWidgetPosition(snapped.l, snapped.t);
                settings.uiLeft = snapped.l;
                settings.uiTop = snapped.t;
                settings.edge = snapped.edge;
                saveSettings();
                applyEdgeClasses();
                suppressClick = true;
                setTimeout(() => { suppressClick = false; }, 120);
                if (ui.panel && !ui.panel.hidden) placePanel();
                return;
            }

            // 没拖动 = 一次点击：自己处理，别等浏览器那下 click（手机上常被吞）
            handleFabTap();
        };

        on(fab, "pointerdown", down);
        on(win, "pointermove", move);
        on(win, "pointerup", up);
        on(win, "pointercancel", up);
    }

    function togglePanel(open) {
        if (!ui.panel) return;
        const next = typeof open === "boolean" ? open : ui.panel.hidden;
        ui.panel.hidden = !next;
        if (ui.widget) ui.widget.classList.toggle("sm-panel-open", next);
        applyEdgeClasses();
        if (next) {
            placePanel();
            renderStatus(); renderList(); renderDetail();
            if (typeof win.requestAnimationFrame === "function") win.requestAnimationFrame(placePanel);
            else setTimeout(placePanel, 0);
        }
    }

    function renderStatus() {
        if (!ui.status) return;
        const chatLen = getChat().length;
        const lastAi = findLastAiIndex(getChat());
        const total = meta.snapshots.length;
        const chars = meta.snapshots.reduce((sum, s) => sum + (Number(s.size) || 0), 0);
        const live = readSamData();
        ui.status.innerHTML = [
            `当前 <b>${lastAi >= 0 ? lastAi : "—"}</b> 层 · 聊天共 ${chatLen} 层`,
            `相册 <b>${total}</b> 张 · 约 ${Math.round(chars / 1024)}KB`,
            `SAM 数据 ${live ? "<b>在线</b>" : "读不到"} · 上限 ${settings.keepCount} 张`
        ].join(" · ");
        renderActions();
    }

    /** 「撤回」按钮的可用状态：有后悔药才亮 */
    function renderActions() {
        if (!ui.undoBtn) return;
        const record = findUndoRecord();
        ui.undoBtn.disabled = !record;
        ui.undoBtn.title = record
            ? `撤回：回到第 ${record.floor} 层贴回之前的样子`
            : "现在没有可以撤回的操作";
    }

    function sourceLabel(source) {
        const map = { sam: "自动", watch: "巡检", undo: "撤回", backfill: "历史", user: "手动" };
        return map[source] || source || "自动";
    }

    function renderList() {
        if (!ui.list) return;
        if (!meta.snapshots.length) {
            ui.list.innerHTML = `<div class="sm-empty">还没有快照。跑一层，它自己就会拍。</div>`;
            return;
        }
        const items = meta.snapshots.slice().sort((a, b) => (Number(b.at) || 0) - (Number(a.at) || 0));

        // 同一层如果有多页，就把页码标出来，免得分不清
        const pageCount = new Map();
        for (const s of items) {
            const key = Number(s.floor);
            pageCount.set(key, (pageCount.get(key) || 0) + 1);
        }

        ui.list.innerHTML = items.map(s => {
            const d = s.digest || {};
            const metaText = `设定 ${d.staticKeys || 0} · 事件 ${d.events || 0} · 记忆 ${(d.L2 || 0) + (d.L3 || 0)}`;
            const badge = s.trimmed ? " · 已瘦身" : "";
            const multiPage = pageCount.get(Number(s.floor)) > 1;
            const pageTag = multiPage ? `<span class="sm-page" title="这一层共有 ${pageCount.get(Number(s.floor))} 页">页 ${Number(s.swipeId) + 1}</span>` : "";
            return `<div class="sm-item${s.id === selectedId ? " active" : ""}" data-id="${escapeHtml(s.id)}">
                <span class="sm-floor" title="${Number(s.floor) === 0 ? "0 层是开场白" : "和酒馆的楼层号一致"}">第 ${Number(s.floor)} 层${pageTag}</span>
                <span class="sm-time">${s.source === "backfill" ? "历史" : escapeHtml(clockText(s.at))}</span>
                <span class="sm-meta">${escapeHtml(metaText + badge)}</span>
                <span class="sm-src ${s.source === "user" ? "user" : ""}">${escapeHtml(sourceLabel(s.source))}</span>
            </div>`;
        }).join("");
    }

    function renderDetail() {
        if (!ui.detail) return;
        if (!selectedId) {
            ui.detail.innerHTML = `<span style="color:#666">点一张快照看看它和现在差在哪。</span>`;
            return;
        }
        const record = meta.snapshots.find(s => s.id === selectedId);
        if (!record) { ui.detail.innerHTML = `<span style="color:#666">这张快照已经不在了。</span>`; return; }
        const live = readSamData();
        if (!live) { ui.detail.innerHTML = `<span style="color:#666">读不到 SAM 的数据，先跑一层再看看。</span>`; return; }

        const diff = CORE.diff(live, record.data);
        const line = (cls, mark, list, max) => list.length
            ? `<div class="${cls}">${mark} ${list.length} 项：${list.slice(0, max).map(escapeHtml).join("、")}${list.length > max ? "…" : ""}</div>`
            : "";

        let jsonBlock = "";
        if (showJson) {
            let jsonText = "";
            try { jsonText = JSON.stringify(record.data, null, 2); } catch (e) { jsonText = "{}"; }
            if (jsonText.length > 20000) jsonText = jsonText.slice(0, 20000) + "\n…（太长，这里只显示前面这段，导出能看到全部）";
            jsonBlock = `<div class="sm-json-hd"><span>这一层存的完整 JSON（和 SAM「数据」栏同一份）</span><button class="sm-btn sm-copy" style="padding:2px 8px;">复制</button></div><pre class="sm-json">${escapeHtml(jsonText)}</pre>`;
        }
        ui.detail.style.maxHeight = showJson ? "44vh" : "160px";

        ui.detail.innerHTML = [
            `<div>这张：第 ${record.floor} 层 · 页 ${record.swipeId + 1} · ${record.source === "backfill" ? "历史回填" : escapeHtml(clockText(record.at))} · ${escapeHtml(sourceLabel(record.source))}</div>`,
            line("sm-diff-add", "＋新增", diff.added, 6),
            line("sm-diff-del", "－消失", diff.removed, 6),
            line("sm-diff-chg", "～改动", diff.changed, 6),
            (diff.added.length + diff.removed.length + diff.changed.length) === 0
                ? `<div class="sm-diff-add">和现在的数据一模一样。</div>` : "",
            (record.changedKeys && record.changedKeys.length)
                ? `<div style="color:#7a7a7a">这一层比上一层动了：${record.changedKeys.map(escapeHtml).join("、")}</div>` : "",
            jsonBlock
        ].filter(Boolean).join("");
    }

    function exportAlbum() {
        try {
            const blob = new Blob([JSON.stringify({ version: VERSION, exportedAt: Date.now(), snapshots: meta.snapshots }, null, 2)], { type: "application/json" });
            const a = doc.createElement("a");
            a.href = URL.createObjectURL(blob);
            a.download = `sam-data-snapshot_${Date.now()}.json`;
            a.click();
            setTimeout(() => { try { URL.revokeObjectURL(a.href); } catch (e) {} }, 4000);
            say("相册导出好了", "success");
        } catch (e) { logger.error(e); say("导出失败", "error"); }
    }

    // ========================================================================
    // 启动
    // ========================================================================
    function stop() {
        cleanups.forEach(fn => { try { fn(); } catch (e) {} });
        cleanups = [];
        if (rollbackTimer) clearTimeout(rollbackTimer);
        if (pollTimer) clearInterval(pollTimer);
        rollbackTimer = null; pollTimer = null;
        try {
            const w = doc && doc.getElementById ? doc.getElementById(WIDGET_ID) : null;
            if (w) w.remove();
            const s = doc && doc.getElementById ? doc.getElementById(STYLE_ID) : null;
            if (s) s.remove();
        } catch (e) {}
        ui.widget = ui.panel = ui.status = ui.list = ui.detail = null;
        logger.info("已停止。");
    }

    function boot() {
        if (typeof SillyTavern === "undefined" || typeof getVariables !== "function") {
            logger.warn("不在酒馆助手环境里，安静待机。");
            return;
        }

        loadSettings();
        loadMeta();
        injectStyle();
        // 界面稍等一下再建，避免和 SAM 抢同一个时机
        setTimeout(() => {
            try { if (buildUI()) renderStatus(); } catch (e) { logger.warn("界面没搭起来，但记录照常。", e); }
            // 老聊天第一次打开：相册是空的，就从过往楼层已有的整本账里回填
            if (!meta.snapshots.length) backfillHistory({ silent: true }).catch(() => {});
            // 回填完再看一眼：和现在不一样就提醒（只提醒，不自动改）
            setTimeout(() => { nudgeOnLoad().catch(() => {}); }, 1400);
        }, 600);

        // SAM 每算完一层 → 拍一张（主力）
        bindEvent(SAM_DONE_EVENT, async () => {
            if (isWriting || isRestoring) return;
            try { await takeSnapshot("sam"); } catch (e) { logger.warn(e); }
        });

        // SAM 要求重新同步 → 同步完再拍一张（兜底）
        bindEvent(SAM_REFRESH_EVENT, async () => {
            if (isWriting || isRestoring) return;
            setTimeout(() => { takeSnapshot("sam").catch(() => {}); }, 800);
        });

        // 生成结束但 SAM 没喊（例如 SAM 关着数据）→ 也补一张
        if (typeof tavern_events !== "undefined") {
            bindEvent(tavern_events.GENERATION_ENDED, () => {
                if (isWriting || isRestoring) return;
                setTimeout(() => { takeSnapshot("sam").catch(() => {}); }, 1200);
            });
            // 删楼：先把那一层的快照清掉，再看要不要恢复上一层
            bindEvent(tavern_events.MESSAGE_DELETED, (message_id) => {
                if (isWriting || isRestoring) return;
                setTimeout(() => { try { pruneDeletedFloors(message_id); } catch (e) { logger.warn(e); } }, 120);
                scheduleRollbackCheck("rollback");
            });
            // 换页 / 编辑：只做比对与恢复
            [tavern_events.MESSAGE_SWIPED, tavern_events.MESSAGE_EDITED]
                .forEach(evt => bindEvent(evt, () => scheduleRollbackCheck("rollback")));
            bindEvent(tavern_events.CHAT_CHANGED, () => {
                if (isWriting || isRestoring) return;
                lastPollHash = "";
                selectedId = null;
                setTimeout(() => {
                    loadMeta(); renderStatus(); renderList(); renderDetail();
                    if (!meta.snapshots.length) backfillHistory({ silent: true }).catch(() => {});
                    setTimeout(() => { nudgeOnLoad().catch(() => {}); }, 1200);
                }, 500);
            });
        }

        startWatcher();

        // 关页面前补最后一张
        if (typeof win !== "undefined" && win.addEventListener) {
            on(win, "beforeunload", () => { try { takeSnapshot("watch"); } catch (e) {} });
        }

        logger.info(`v${VERSION} 已就位。`);
    }

    // 旧实例先停掉，热重载不叠加
    try {
        if (win[INSTANCE_KEY] && typeof win[INSTANCE_KEY].stop === "function") win[INSTANCE_KEY].stop();
    } catch (e) {}
    win[INSTANCE_KEY] = { stop, core: CORE, takeSnapshot, restoreSnapshot, backfillHistory, get meta() { return meta; } };

    boot();
})());
